        if (start + size > bytes.length)
            throw invalid();
        if (text(offset) === 'fmt ') {
            if (size < 16 || view.getUint16(start, true) !== 1)
                throw invalid();
            const channels = view.getUint16(start + 2, true), rate = view.getUint32(start + 4, true), bits = view.getUint16(start + 14, true);
